cd /workspace && python3 - <<'EOF'
import json, random
rng = random.Random(7)
n = 96
edges=[]
def e(u,v,lab): edges.append({"u":u,"v":v,"ping_us":1,"ack_us":1,"label":lab})
for k in range(3): e(0,1+k,"a%d"%k)
for L in range(7):
    b=1+L*3; nx=1+(L+1)*3
    if L==6: nx=95
    for a in range(3):
        for b2 in range(3): e(b+a,nx+b2,"L")
pairs=[(u,v) for u in range(22,95) for v in range(u+1,95)]
rng.shuffle(pairs)
for (u,v) in pairs[:384-len(edges)]:
    e(u,v,"z")
print("edges",len(edges))
print("max u",max(x["u"] for x in edges),"max v",max(x["v"] for x in edges))
out=[[] for _ in range(n)]
for i,ed in enumerate(edges): out[ed["u"]].append(i)
cnt=[0]*n; cnt[n-1]=1
for v in range(n-2,-1,-1):
    cnt[v]=sum(cnt[edges[i]["v"]] for i in out[v])
print("paths",cnt[0])
EOF
